#!/usr/bin/env node
/**
 * Copies the manual (docs/help/*.md) into src/lib/help/help-docs.generated.ts,
 * so the Help Centre can import it: Next.js has no import.meta.glob, and the
 * frontend's Docker build does not see the repo's docs/ folder.
 *
 * Runs before `next dev` and `next build`; `npm run help:build` runs it by
 * hand. The generated file is committed, and help-content.test.ts fails when
 * it is out of date with docs/help.
 *
 *   node scripts/build-help-content.mjs          write the file
 *   node scripts/build-help-content.mjs --check  exit 1 if it is stale
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const frontend = join(dirname(fileURLToPath(import.meta.url)), '..');
const helpDir = join(frontend, '..', 'docs', 'help');
const outFile = join(frontend, 'src', 'lib', 'help', 'help-docs.generated.ts');

export function renderHelpModule(dir = helpDir) {
  const files = existsSync(dir) ? readdirSync(dir).filter((name) => name.endsWith('.md')).sort() : [];
  const entries = files.map((name) => `  ${JSON.stringify(name)}: ${JSON.stringify(readFileSync(join(dir, name), 'utf8'))},`);
  return [
    '// Generated by scripts/build-help-content.mjs from docs/help/*.md. Do not edit:',
    '// change the markdown and run `npm run help:build`.',
    '',
    'export const rawHelpDocs: Record<string, string> = {',
    ...entries,
    '};',
    '',
  ].join('\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  // A build that cannot see docs/ (the frontend's Docker image) keeps the committed copy.
  if (!existsSync(helpDir)) {
    console.log('help: docs/help not found; keeping the committed help-docs.generated.ts');
    process.exit(0);
  }
  const next = renderHelpModule();
  const current = existsSync(outFile) ? readFileSync(outFile, 'utf8') : '';
  if (process.argv.includes('--check')) {
    if (next !== current) {
      console.error('src/lib/help/help-docs.generated.ts is out of date with docs/help: run `npm run help:build`.');
      process.exit(1);
    }
  } else if (next !== current) {
    writeFileSync(outFile, next);
    console.log(`help: bundled ${next.split('\n').filter((line) => line.startsWith('  "')).length} pages from docs/help`);
  }
}
